-- ============================================================
--  Paisa Bachao — MySQL Schema
--  Generated by setup.js (also runnable manually)
--
--  Manual usage:
--    mysql -u root -p < server/schema.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS paisa_bachao
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE paisa_bachao;

-- ── users ────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS users (
  id                 INT AUTO_INCREMENT PRIMARY KEY,
  name               VARCHAR(100)  NOT NULL,
  email              VARCHAR(150)  NOT NULL UNIQUE,
  password_hash      VARCHAR(255)  DEFAULT NULL        COMMENT 'NULL for Google-only accounts',
  google_id          VARCHAR(255)  DEFAULT NULL,
  avatar_url         VARCHAR(500)  DEFAULT NULL,
  monthly_allowance  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  needs_percentage   INT           NOT NULL DEFAULT 60  COMMENT 'Must sum to 100 with wants_percentage',
  wants_percentage   INT           NOT NULL DEFAULT 40,
  currency           VARCHAR(10)   NOT NULL DEFAULT '₹',
  created_at         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── transactions ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS transactions (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  user_id     INT           NOT NULL,
  title       VARCHAR(200)  NOT NULL,
  amount      DECIMAL(10,2) NOT NULL,
  type        ENUM('needs','wants') NOT NULL,
  subcategory VARCHAR(100)  NOT NULL,
  date        DATE          NOT NULL,
  note        TEXT          DEFAULT NULL,
  created_at  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_transactions_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── indexes ──────────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_tx_user_id ON transactions (user_id);
CREATE INDEX IF NOT EXISTS idx_tx_date    ON transactions (date);
CREATE INDEX IF NOT EXISTS idx_tx_type    ON transactions (type);

